@import 'tailwindcss';

@theme {
  --color-canvas: #090b10;
  --color-surface: #11141b;
  --color-raised: #171b24;
  --color-line: #232935;
  --color-line-strong: #333b4b;

  --color-ink: #eef1f7;
  --color-ink-muted: #98a2b6;
  --color-ink-faint: #5a6376;

  --color-glow: #3ce69b;
  --color-glow-soft: #17402f;
  --color-glow-dim: #1d5540;

  --color-ref: #f7b955;
  --color-warn: #fb7e6d;

  --font-sans: 'Inter var', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-mono: ui-monospace, 'SF Mono', 'JetBrains Mono', Menlo, monospace;
}

@layer base {
  html {
    color-scheme: dark;
  }

  body {
    margin: 0;
    min-height: 100svh;
    background-color: var(--color-canvas);
    /* Two faint pools of light so the flat dark canvas has some depth. */
    background-image:
      radial-gradient(ellipse 80% 50% at 50% -10%, rgba(60, 230, 155, 0.07), transparent),
      radial-gradient(ellipse 60% 40% at 90% 0%, rgba(247, 185, 85, 0.045), transparent);
    background-repeat: no-repeat;
    color: var(--color-ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }

  :focus-visible {
    outline: 2px solid var(--color-glow);
    outline-offset: 2px;
    border-radius: 4px;
  }

  button {
    font: inherit;
    color: inherit;
  }
}

@utility tnum {
  font-variant-numeric: tabular-nums;
}

/* Overlap cells carry a soft bloom so a valid window is visible at a glance. */
@utility cell-overlap {
  background-color: var(--color-glow-soft);
  border-color: var(--color-glow-dim);
  color: var(--color-glow);
  box-shadow: inset 0 0 0 1px rgba(60, 230, 155, 0.14);
}

