  /*
   * The header and every city row share this template, which is what makes a
   * column of overlap read as one unbroken block. The columns tighten below
   * 1024px so all 24 hours stay on screen at the desktop breakpoint — the grid
   * is useless if part of the day is hidden behind a scrollbar.
   */
  .hour-grid {
    display: grid;
    --city-col: 11rem;
    --cell-min: 1.75rem;
    --action-col: 2.25rem;
    grid-template-columns:
      var(--city-col)
      repeat(24, minmax(var(--cell-min), 1fr))
      var(--action-col);
    column-gap: 1px;
  }

  @media (width < 64rem) {
    .hour-grid {
      --city-col: 7.5rem;
      --cell-min: 1.1rem;
      --action-col: 1.5rem;
    }

    .hour-grid .hour-cell-value {
      font-size: 10px;
    }
  }
}

