for (const w of [768, 900, 1280]) {
  await page.setViewportSize({ width: w, height: 900 });
  await page.waitForTimeout(250);
  out["shot" + w] = await saveScreenshot(await page.screenshot({ fullPage: true }), `tz-${w}.png`);
  out["clipped" + w] = await page.evaluate(() => {
    const scroller = document.querySelector(".overflow-x-auto");
    return scroller ? scroller.scrollWidth - scroller.clientWidth : null;
  });
}
console.log(JSON.stringify({ ...out, errors }, null, 2));
EOF

